"""Generates crates/af-core/src/element_tables.rs from the C++ reference dump
(tests/golden/elements.json), so the Rust tables equal the C++ ones exactly.
Run from rust/: python tools/gen_elements.py"""
import json

data = json.load(open('tests/golden/elements.json', encoding='utf-8'))
els = data['elements']
schemes = data['schemes']


def f32(v):
    s = repr(float(v))
    return s if ('.' in s or 'e' in s) else s + '.0'


out = ['// Generated by tools/gen_elements.py from tests/golden/elements.json (the C++',
       '// util/ElementData and util/ElementColourSchemes tables). Do not edit.',
       '',
       'pub(crate) const SYMBOLS: [&str; 119] = [' + ', '.join(json.dumps(e['symbol'] if e['z'] else '') for e in els) + '];',
       'pub(crate) const NAMES: [&str; 119] = [' + ', '.join(json.dumps(e['name'] if e['z'] else '') for e in els) + '];',
       'pub(crate) const COVALENT_RADII: [f32; 119] = [' + ', '.join(f32(e['covalent_radius']) for e in els) + '];',
       'pub(crate) const MASSES: [f64; 119] = [' + ', '.join(f32(e['mass']) for e in els) + '];',
       'pub(crate) const DEFAULT_COLOURS: [[f32; 3]; 119] = [' + ', '.join('[' + ', '.join(f32(c) for c in e['colour']) + ']' for e in els) + '];',
       'pub(crate) const SCHEME_NAMES: [&str; %d] = [%s];' % (len(schemes), ', '.join(json.dumps(s['name']) for s in schemes)),
       'pub(crate) const SCHEME_DESCRIPTIONS: [&str; %d] = [%s];' % (len(schemes), ', '.join(json.dumps(s['description']) for s in schemes)),
       'pub(crate) const SCHEME_COLOURS: [[[f32; 3]; 119]; %d] = [' % len(schemes)]
for s in schemes:
    out.append('    [' + ', '.join('[' + ', '.join(f32(c) for c in col) + ']' for col in s['colours']) + '],')
out.append('];')
open('crates/af-core/src/element_tables.rs', 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
print('elements', len(els), 'schemes', len(schemes))
